#include <string>
#include <vector>

enum class Estado {
    preparado,
    enviado,
    cancelado
};

struct PedidoInvalido {};

class Pedido {
public:
    Pedido(std::string codigo, int unidades)
        : codigo_{codigo}, unidades_{unidades} {
        if (codigo_.empty() || unidades_ < 1 || unidades_ > 20) {
            throw PedidoInvalido{};
        }
    }

    std::string codigo() const {
        return codigo_;
    }

    int unidades() const {
        return unidades_;
    }

    Estado estado() const {
        return estado_;
    }

    bool cambiar_unidades(int nuevas) {
        if (estado_ != Estado::preparado || nuevas < 1 || nuevas > 20) {
            return false;
        }

        unidades_ = nuevas;
        return true;
    }

    bool enviar() {
        if (estado_ != Estado::preparado) {
            return false;
        }

        estado_ = Estado::enviado;
        return true;
    }

    bool cancelar() {
        if (estado_ != Estado::preparado) {
            return false;
        }

        estado_ = Estado::cancelado;
        return true;
    }

private:
    std::string codigo_;
    int unidades_;
    Estado estado_ = Estado::preparado;
};

