    Pedido pedido{"M", 4};

    std::cout << pedido.cambiar_unidades(7) << ":"
              << pedido.unidades() << "\n";
    std::cout << pedido.cambiar_unidades(0) << ":"
              << pedido.unidades() << "\n";
    std::cout << pedido.enviar() << ":"
              << (pedido.estado() == Estado::enviado) << "\n";
    std::cout << pedido.cancelar() << ":"
              << (pedido.estado() == Estado::enviado) << "\n";
    std::cout << pedido.cambiar_unidades(2) << ":"
              << pedido.unidades();

    return 0;
}

